const categories = rawCategories.map((row) => ({
  category_id: Number(row.databaseId),
  name: cleanText(row.name),
  slug: String(row.slug ?? ''),
  active: true,
})).filter((row) => Number.isInteger(row.category_id) && row.category_id > 0 && row.name && row.slug);
const tags = rawTags.map((row) => ({
  tag_id: Number(row.databaseId),
  name: cleanText(row.name),
  slug: String(row.slug ?? ''),
  active: true,
})).filter((row) => Number.isInteger(row.tag_id) && row.tag_id > 0 && row.name && row.slug);
const catalogValid = errors.length === 0 && posts.length > 0 && categories.length > 0 && tags.length > 0;
const warnings = [...base.warnings];
if (errors.length > 0) warnings.push({ code: 'WPGRAPHQL_ERRORS_RETURNED', severity: 'BLOCKER' });
if (posts.length === 0) warnings.push({ code: 'WPGRAPHQL_POST_CATALOG_EMPTY', severity: 'BLOCKER' });
