const data = $input.first().json;
function terms(value) {
  return new Set(String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/gu, '').toLowerCase().replace(/[^a-z0-9\s-]/gu, ' ').split(/\s+/u).filter((term) => term.length > 3));
